CREATE TABLE ezdfsfile (name_hash VARCHAR(34) DEFAULT '' NOT NULL, name TEXT NOT NULL, name_trunk TEXT NOT NULL, datatype VARCHAR(255) DEFAULT 'application/octet-stream' NOT NULL, scope VARCHAR(25) DEFAULT '' NOT NULL, size BIGINT UNSIGNED DEFAULT 0 NOT NULL, mtime INT DEFAULT 0 NOT NULL, expired TINYINT(1) DEFAULT '0' NOT NULL, status TINYINT(1) DEFAULT '0' NOT NULL, INDEX ezdfsfile_name_trunk (name_trunk(191)), INDEX ezdfsfile_expired_name (expired, name(191)), INDEX ezdfsfile_name (name(191)), INDEX ezdfsfile_mtime (mtime), PRIMARY KEY(name_hash)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
